"""Islamiat (Ikhtiari) XII PDF60: pp.110–111 — some Hadith terms; kinds of Hadith. Run: python class12_iski_page060.py"""
from class12_iski_common import BOOK, Builder, rec, P, L, AR


def p60():
    b = Builder()
    b.h('Explanation of some terms of Hadith', 'چند اصطلاحاتِ حدیث کی وضاحت', 'د حدیث د ځینو اصطلاحاتو وضاحت')
    L(b, [('1) Rawi (narrator): one who reports a hadith is called a rawi, that is, (Reporter).', '1) راوی: حدیث نقل (Report) کرنے والے کو راوی کہتے ہیں۔ یعنی (Reporter)۔', '۱) راوي: هغه چاته چې حدیث نقل (Report) کړي، راوي وايي، یعنې (Reporter).'),
          ('2) Sanad (chain): by it is meant that chain of narrators which reaches up to the words of the hadith.', '2) سند: اس سے مراد راویوں کا وہ سلسلہ ہے جو الفاظِ حدیث تک پہنچتا ہے۔', '۲) سند: له دې څخه د راویانو هغه لړۍ مراد ده چې د حدیث تر الفاظو رسېږي.'),
          ('3) Matn (text): by it are meant the words of the hadith after the chain of narrators. Its example is as follows:', '3) متن: اس سے مراد راویوں کے سلسلے کے بعد الفاظِ حدیث ہیں۔ اس کی مثال حسبِ ذیل ہے:', '۳) متن: له دې څخه د راویانو له لړۍ وروسته د حدیث الفاظ مراد دي. بېلګه یې دا ده:')])
    AR(b, '"حدثنا الحُمَيْدی حدثنا سُفْيَانُ حدثنا يحيىٰ بن سعيد اخبرنی محمد بن ابراهيم انهٗ سمع علقمة بن وقاص يقول سمعتُ عمر بن الخطاب رضی الله عنه على المنبر" قال سمعتُ رسول الله صلى الله عليه وسلم يقول (اِنَّمَا الْاَعْمَالُ بِالنِّيَّاتِ)')
    b.p('In this hadith, the names mentioned between the inverted commas (comma) are the sanad of this hadith, and the text between the brackets is its matn. The sanad of a hadith consists of the narrators of the hadith.', 'اس حدیث میں واوین (کامہ) کے درمیان جو نام مذکور ہیں یہ اس حدیث کی سند ہے اور بریکٹ کے درمیان جو عبارت ہے وہ متن ہے۔ سند حدیث کے راویوں پر مشتمل ہوتی ہے۔', 'په دې حدیث کې د واوینو (کامه) ترمنځ چې کوم نومونه یاد شوي، هغه د دې حدیث سند دی، او د قوسونو ترمنځ چې کوم عبارت دی، هغه متن دی. سند د حدیث له راویانو جوړ وي.')
    L(b, [('4) Sahabi (Companion): one who, in the state of faith, saw the Noble Prophet ﷺ and kept his ﷺ company, and died upon Islam.', '4) صحابی: جس نے ایمان کی حالت میں نبی کریم صلی اللہ علیہ وآلہٖ وسلم کی زیارت کی ہو اور آپؐ کی صحبت اختیار کی ہو اور اسلام پر وفات پا چکا ہو۔', '۴) صحابي: هغه څوک چې د ایمان په حالت کې یې د نبي کریم ﷺ زیارت کړی وي، د هغه ﷺ صحبت یې غوره کړی وي او پر اسلام وفات شوی وي.'),
          ('5) Tabi\'i (Successor): one who, in the state of faith, saw a Companion and died in the state of Islam.', '5) تابعی: جس نے ایمان کی حالت میں صحابی کی زیارت کی ہو اور حالتِ اسلام میں ہی وفات ہوئے۔', '۵) تابعي: هغه څوک چې د ایمان په حالت کې یې د صحابي زیارت کړی وي او د اسلام په حالت کې وفات شوی وي.')])
    b.h('Kinds of Hadith', 'اقسامِ حدیث', 'د حدیث ډولونه')
    P(b, [('The kinds of Hadith are somewhat more than 100, of which the important ones are mentioned below.', 'حدیث کی اقسام 100 سے کچھ زائد ہیں جن میں سے اہم کو ذیل میں ذکر کیا جاتا ہے۔', 'د حدیث ډولونه له ۱۰۰ څخه یو څه زیات دي، چې مهم یې لاندې یادېږي.'),
          ('Hadith basically has two kinds.', 'حدیث کی بنیادی طور پر دو قسمیں ہیں۔', 'حدیث په بنسټیز ډول دوه ډوله دی.')])
    L(b, [('• Khabar mutawatir: this is that hadith whose narrators in every age are so many that sound intellect considers it impossible for all of them to have agreed upon a lie. Certain knowledge is obtained from khabar mutawatir, and there is no criticism of its sanad.', '• خبرِ متواتر: یہ وہ حدیث ہے کہ جس کے راوی ہر زمانے میں اس قدر زیادہ ہوں کہ عقلِ سلیم ان سب کے جھوٹ پر اتفاق کر لینے کو محال سمجھتی ہو۔ خبرِ متواتر سے علمِ یقینی حاصل ہوتا ہے اور اس کی سند کی تنقید نہیں ہوتی ہے۔', '• خبر متواتر: هغه حدیث دی چې راویان یې په هر زمانه کې دومره ډېر وي چې سلیم عقل د دوی ټولو پر دروغو اتفاق ناشونی ګڼي. له خبر متواتر یقیني علم ترلاسه کېږي، او د سند نقد یې نه کېږي.'),
          ('• Khabar wahid: this is that hadith whose narrators are not so many. Khabar wahid, with respect to its end-point, is of four kinds.', '• خبرِ واحد: یہ وہ حدیث ہے کہ جس کے راوی اتنے زیادہ نہ ہوں۔ خبرِ واحد اپنے منتہا کے اعتبار سے چار قسم پر ہے۔', '• خبر واحد: هغه حدیث دی چې راویان یې دومره ډېر نه وي. خبر واحد د خپل منتها (پای) له مخې څلور ډوله دی.')])
    r1 = rec(b, 2, 110, 60, [110])
    t = Builder()
    t.h('Kinds of khabar with respect to chains (isnad)', 'اقسامِ خبر بلحاظِ اسناد', 'د اسناد له مخې د خبر ډولونه')
    L(t, [('• Hadith marfu\': this is that hadith in which a saying, deed, tacit approval or attribute of the Noble Prophet ﷺ is mentioned, and some Companion states it.', '• حدیثِ مرفوع: یہ وہ حدیث ہے کہ جس میں نبی اکرم صلی اللہ علیہ وآلہٖ وسلم کے قول یا فعل یا تقریر یا صفت کا ذکر ہو اور اسے کوئی صحابی بیان کرے۔', '• مرفوع حدیث: هغه حدیث دی چې په کې د نبي اکرم ﷺ قول، فعل، تقریر یا صفت یاد شوی وي او کوم صحابي یې بیان کړي.'),
          ('• Hadith mawquf: this is that hadith in which the saying, deed or tacit approval of a Companion is mentioned.', '• حدیثِ موقوف: یہ وہ حدیث ہے کہ جس میں صحابی کا قول یا فعل یا تقریر مذکور ہو۔', '• موقوف حدیث: هغه حدیث دی چې په کې د صحابي قول، فعل یا تقریر یاد شوی وي.'),
          ('• Hadith maqtu\': this is that hadith in which the saying, deed or tacit approval of a Tabi\'i is mentioned.', '• حدیثِ مقطوع: یہ وہ حدیث ہے کہ جس میں تابعی کے قول یا فعل یا تقریر کا ذکر ہو۔', '• مقطوع حدیث: هغه حدیث دی چې په کې د تابعي قول، فعل یا تقریر یاد شوی وي.')])
    t.h('Kinds of khabar with respect to narrators', 'اقسامِ خبر بلحاظِ رواۃ', 'د راویانو له مخې د خبر ډولونه')
    t.p('☆ Khabar wahid, with respect to the number of narrators, is of three kinds.', '☆ خبرِ واحد: خبرِ واحد راویوں کے تعداد سے تین قسم پر ہے۔', '☆ خبر واحد د راویانو د شمېر له مخې درې ډوله دی.')
    L(t, [('1) Khabar mashhur: this is that hadith whose narrators are in no age fewer than three, but it does not reach the level of mutawatir.', '1) خبرِ مشہور: یہ وہ حدیث ہے جس کے راوی کسی زمانے میں بھی تین سے کم نہ ہوں البتہ متواتر کی حد تک نہ پہنچے۔', '۱) خبر مشهور: هغه حدیث دی چې راویان یې په هېڅ زمانه کې له دریو کم نه وي، خو د متواتر تر کچې ونه رسېږي.'),
          ('2) Khabar \'aziz: this is that hadith whose narrators are in no age fewer than two.', '2) خبرِ عزیز: یہ وہ حدیث ہے کہ جس کے راوی کسی زمانہ میں بھی دو سے کم نہ ہوں۔', '۲) خبر عزیز: هغه حدیث دی چې راویان یې په هېڅ زمانه کې له دوو کم نه وي.'),
          ('3) Khabar gharib: this is that hadith in whose sanad, somewhere or other, only one narrator remains.', '3) خبرِ غریب: یہ وہ حدیث ہے جس کی سند میں کہیں نہ کہیں صرف ایک راوی رہ جائے۔', '۳) خبر غریب: هغه حدیث دی چې په سند کې یې چېرته نه چېرته یوازې یو راوي پاتې شي.')])
    t.h('Kinds of khabar with respect to the qualities of narrators', 'اقسامِ خبر بلحاظِ صفات الرواۃ', 'د راویانو د صفاتو له مخې د خبر ډولونه')
    t.p('☆ Khabar wahid, with respect to the qualities of its narrators, is of 12 kinds.', '☆ خبرِ واحد اپنے راویوں کی صفات کے اعتبار سے 12 قسموں پر ہے۔', '☆ خبر واحد د خپلو راویانو د صفاتو له مخې ۱۲ ډوله دی.')
    L(t, [('1) Sahih li-dhatihi: this is that hadith all of whose narrators are of perfect precision, the sanad is connected, and no hidden defect or irregularity is found in it.', '1) صحیح لذاتہ: یہ وہ حدیث ہے کہ جس کے تمام راوی کامل الضبط ہوں، سند متصل ہو اور اس میں علت اور شذوذ نہ پایا جائے۔', '۱) صحیح لذاته: هغه حدیث دی چې ټول راویان یې د بشپړ ضبط خاوندان وي، سند یې متصل وي، او په کې علت او شذوذ ونه موندل شي.'),
          ('2) Hasan li-dhatihi: this is that hadith in which all the qualities of sahih li-dhatihi are present, but some deficiency is found in memory and precision.', '2) حسن لذاتہ: یہ وہ حدیث ہے کہ جس میں صحیح لذاتہ کی تمام صفات موجود ہوں لیکن حفظ و ضبط میں کچھ نقصان پایا جائے۔', '۲) حسن لذاته: هغه حدیث دی چې د صحیح لذاته ټول صفات په کې وي، خو په حفظ او ضبط کې یو څه کمی وموندل شي.'),
          ('3) Da\'if (weak): this is that hadith among whose narrators the conditions of sahih li-dhatihi and hasan li-dhatihi are not present.', '3) ضعیف: یہ وہ حدیث ہے کہ جس کے راویوں میں صحیح لذاتہ اور حسن لذاتہ کی شرائط موجود نہ ہوں۔', '۳) ضعیف: هغه حدیث دی چې په راویانو کې یې د صحیح لذاته او حسن لذاته شرطونه نه وي.'),
          ('4) Sahih li-ghayrihi: this is that hadith which was originally hasan li-dhatihi, but its several chains were found, so it became sahih li-ghayrihi.', '4) صحیح لغیرہ: یہ وہ حدیث ہے جو اصل میں حسن لذاتہ تھی لیکن اس کی سندیں متعدد پائی گئیں تو یہ صحیح لغیرہ بن گئی۔', '۴) صحیح لغیره: هغه حدیث دی چې په اصل کې حسن لذاته و، خو ډېر سندونه یې وموندل شول، نو صحیح لغیره شو.'),
          ('5) Hasan li-ghayrihi: this is that weak hadith which has many chains.', '5) حسن لغیرہ: یہ وہ ضعیف حدیث ہے کہ جس کی بہت سی سندیں ہوں۔', '۵) حسن لغیره: هغه ضعیف حدیث دی چې ډېر سندونه ولري.'),
          ('6) Mawdu\' (fabricated): that hadith is called so, in which a lie in hadith is proved against one of its narrators.', '6) موضوع: اس حدیث کو کہتے ہیں کہ جس کے کسی راوی سے حدیث میں جھوٹ ثابت ہو۔', '۶) موضوع: هغه حدیث ته وايي چې د کوم راوي یې په حدیث کې دروغ ثابت شي.'),
          ('7) Matruk (abandoned): that hadith whose narrator is accused of lying, or whose narration is against the known facts of religion and established rules.', '7) متروک: جس حدیث کے راوی پر جھوٹ بولنے کا الزام ہو یا اس کی روایت دین کے معلوم اور مسلّم قواعد کے خلاف ہو۔', '۷) متروک: هغه حدیث چې پر راوي یې د دروغو تور وي، یا روایت یې د دین له معلومو او منلو قواعدو خلاف وي.'),
          ('8) Shadhdh (irregular): this is that narration whose narrator is himself trustworthy, but he is contradicting more trustworthy narrators than himself.', '8) شاذ: یہ وہ روایت ہے کہ جس کا راوی تو خود ثقہ ہے لیکن وہ اپنے سے زیادہ ثقات کی مخالفت کر رہا ہو۔', '۸) شاذ: هغه روایت دی چې راوي یې پخپله ثقه وي، خو له ځانه د ډېرو ثقه راویانو مخالفت کوي.'),
          ('9) Mahfuz (preserved): that narration which is opposite to the shadhdh.', '9) محفوظ: وہ روایت جو شاذ کے مقابل ہو۔', '۹) محفوظ: هغه روایت چې د شاذ پر وړاندې وي.'),
          ('10) Munkar (denounced): that hadith whose narrator, despite being weak, is contradicting the trustworthy.', '10) منکر: وہ حدیث ہے کہ جس کا راوی ضعیف ہونے کے باوجود ثقات کی مخالفت کر رہا ہو۔', '۱۰) منکر: هغه حدیث دی چې راوي یې له ضعیف کېدو سره سره د ثقه راویانو مخالفت کوي.')])
    BOOK.save(60, [(2, r1), (2, rec(t, 2, 111, 60, [111]))], issues=[{'id': 'iski12-pdf060', 'unit': 2, 'printedPage': 110,
               'description': 'p.110 says khabar wahid "is of four kinds" by its end-point, but p.111 lists three (marfu\', mawquf, maqtu\') — kept as printed. The isnad example is printed with an English-style comma explanation "(کامہ)" — kept. "12 قسموں" list continues on p.112. Neighbouring book covers at the scan edge excluded.'}])


if __name__ == '__main__':
    p60()
